# owner: platform
import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span


class RoundedLabelsTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 10)]
        self.assertEqual(
            rounded_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
